INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(51831560, 'Gem-Knight Nepyrim', '宝石骑士・拿碧利', 'ジェムナイト・ネピリム', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1550, 1600, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「宝石骑士·拿非琉」以外的1张「宝石骑士」卡加入手卡。这个回合的主要阶段内，对方受到的效果伤害变成一半。 ②：自己主要阶段才能发动。进行1只「宝石」怪兽的召唤。 ③：这张卡从手卡·卡组送去墓地的场合才能发动。选自己1张手卡送去墓地，这张卡特殊召唤。'),
(19163116, 'Gem-Knight Obsidian', '宝石骑士・黑曜石', 'ジェムナイト・オブシディア', 'Effect Monster', 'Rock', 'EARTH', 3, 1500, 1200, '①：这张卡从手卡送去墓地的场合，以自己墓地1只4星以下的通常怪兽为对象才能发动。那只怪兽特殊召唤。'),
(71594310, 'Gem-Knight Pearl', '宝石骑士・珍珠', 'ジェムナイト・パール', 'XYZ Monster', 'Rock', 'EARTH', 4, 2600, 1900, '4星怪兽×2'),
(24484270, 'Gem-Knight Phantom Quartz', '宝石骑士・魅影原核', 'ジェムナイト・ファントムルーツ', 'Link Monster', 'Rock', 'EARTH', NULL, 1450, NULL, '「宝石」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「宝石骑士」卡加入手卡。 ②：支付1000基本分才能发动。自己的墓地·除外状态的怪兽作为融合素材回到卡组，把1只「宝石骑士」融合怪兽融合召唤。这个效果特殊召唤的怪兽在这个回合不能直接攻击。'),
(93379652, 'Gem-Knight Prismaura', '宝石骑士・光棱晶', 'ジェムナイト・プリズムオーラ', 'Fusion Monster', 'Thunder', 'EARTH', 7, 2450, 1400, '「宝石骑士」怪兽＋雷族怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：1回合1次，从手卡把1张「宝石骑士」卡送去墓地，以场上1张表侧表示卡为对象才能发动。那张表侧表示卡破坏。'),
(35622739, 'Gem-Knight Quartz', '宝石骑士・石英', 'ジェムナイト・クォーツ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上有怪兽存在的场合，把这张卡从手卡丢弃才能发动。从卡组把1张「融合」永续魔法卡在自己场上盖放。这个回合，自己不是「宝石骑士」怪兽不能从额外卡组特殊召唤。 ②：这张卡成为融合召唤的素材，被送去墓地的场合或者被除外的场合才能发动。从自己墓地把「宝石骑士·石英」以外的1只「宝石骑士」怪兽加入手卡。'),
(76614340, 'Gem-Knight Ruby', '宝石骑士・红玉', 'ジェムナイト・ルビーズ', 'Fusion Monster', 'Pyro', 'EARTH', 6, 2500, 1300, '「宝石骑士·红榴」＋「宝石骑士」怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。 ①：1回合1次，把自己场上1只其他的表侧表示的「宝石」怪兽解放才能发动。这张卡的攻击力直到回合结束时上升解放的怪兽的攻击力数值。 ②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(27126980, 'Gem-Knight Sapphire', '宝石骑士・苍玉石', 'ジェムナイト・サフィア', 'Normal Monster', 'Aqua', 'EARTH', 4, NULL, 2100, '利用蓝宝石力量将水操纵自如，并温柔地包住来自敌人的攻击。那宁静的守护似乎深受同伴信赖。'),
(43114901, 'Gem-Knight Sardonyx', '宝石骑士·红缟', 'ジェムナイト・サニクス', 'Gemini Monster', 'Pyro', 'EARTH', 4, 1800, 900, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡战斗破坏对方怪兽送去墓地时，可以从自己卡组把1张名字带有「宝石骑士」的卡加入手卡。'),
(3113836, 'Gem-Knight Seraphinite', '宝石骑士・绿龙晶', 'ジェムナイト・セラフィ', 'Fusion Monster', 'Fairy', 'EARTH', 5, 2300, 1400, '「宝石骑士」怪兽＋光属性怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。 ①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只怪兽通常召唤。'),
(49597193, 'Gem-Knight Topaz', '宝石骑士・黄玉', 'ジェムナイト・パーズ', 'Fusion Monster', 'Thunder', 'EARTH', 6, 1800, 1800, '「宝石骑士·黄碧」＋「宝石骑士」怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。 ①：这张卡在同1次的战斗阶段中可以作2次攻击。 ②：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(54620698, 'Gem-Knight Tourmaline', '宝石骑士・电气石', 'ジェムナイト・ルマリン', 'Normal Monster', 'Thunder', 'EARTH', 4, 1600, 1800, '会以黄碧玺力量生出神奇能量，并变为战力来战斗哟。他刺激的生活方式引起宝石族许多共鸣。'),
(8692301, 'Gem-Knight Zirconia', '宝石骑士・锆晶', 'ジェムナイト・ジルコニア', 'Fusion Monster', 'Rock', 'EARTH', 8, 2900, 2500, '「宝石骑士」怪兽＋岩石族怪兽'),
(53408006, 'Gem-Merchant', '宝石商人', 'ジェム・マーチャント', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1000, 1000, '自己场上表侧表示存在的地属性的通常怪兽进行战斗的伤害步骤时可以把这张卡从手卡送去墓地，那只怪兽的攻击力·守备力直到这个回合的结束阶段时上升1000。'),
(64734090, 'Gem-Turtle', '宝石龟', 'ジェムタートル', 'Flip Effect Monster', 'Rock', 'EARTH', 4, NULL, 2000, '反转：可以从自己卡组把1张「宝石骑士融合」加入手卡。'),
(80758812, 'Gemini Ablation', '二重烧蚀', 'デュアル・アブレーション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，可以丢弃1张手卡，从以下效果选择1个发动。 ●从卡组把1只二重怪兽特殊召唤。这个效果特殊召唤的怪兽当作再1次召唤的状态使用。 ●自己场上1只二重怪兽解放，从手卡·卡组把1只战士族·炎属性怪兽特殊召唤。把再1次召唤状态的二重怪兽解放的场合，可以再选场上1张卡破坏。'),
(18096222, 'Gemini Booster', '二重推进器', 'デュアル・ブースター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只二重怪兽为对象才能把这张卡发动。这张卡当作攻击力上升700的装备卡使用给那只自己怪兽装备。 ②：当作装备卡使用的这张卡被破坏送去墓地的场合，以场上1只二重怪兽为对象发动。那只二重怪兽变成再1次召唤的状态。'),
(81601517, 'Gemini Counter', '受害者的反击', 'ヴィクティム・カウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的1只二重怪兽变成里侧守备表示，对方的魔法卡的发动无效并破坏。'),
(69140098, 'Gemini Elf', '双生精灵', 'ヂェミナイ・エルフ', 'Normal Monster', 'Spellcaster', 'EARTH', 4, 1900, 900, '交替发动攻击的精灵双子姐妹。'),
(67688478, 'Gemini Imps', '双生恶魔', 'ヂェミナイ・デビル', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1000, '包含把自己手卡丢弃的效果的卡由对方发动时，可以通过把这张卡从手卡送去墓地来让那个发动和效果无效，那张卡破坏然后从自己卡组抽1张卡。'),
(26254876, 'Gemini Lancer', '二重枪兵', 'デュアル・ランサー', 'Gemini Monster', 'Sea Serpent', 'WATER', 4, 1800, 1400, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(91798373, 'Gemini Scorpion', '双蝎', 'デュアル・スコーピオン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 400, '这张卡召唤·特殊召唤成功时，可以从手卡把1只4星以下的二重怪兽特殊召唤。'),
(68366996, 'Gemini Soldier', '二重士兵', 'デュアル・ソルジャー', 'Gemini Monster', 'Warrior', 'WIND', 2, 500, 300, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡1回合只有1次不会被战斗破坏。这张卡进行战斗的场合，那次伤害计算后可以从自己卡组把「二重士兵」以外的1只4星以下的二重怪兽在自己场上特殊召唤。'),
(33846209, 'Gemini Spark', '二重电光', 'デュアルスパーク', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只表侧表示的4星二重怪兽解放，以场上1张卡为对象才能发动。那张卡破坏，自己从卡组抽1张。'),
(19041767, 'Gemini Summoner', '二重召唤师', 'デュアル・サモナー', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1500, NULL, '对方的结束阶段时只有1次支付500基本分才能发动。把手卡或者自己场上表侧表示存在的1只二重怪兽通常召唤。此外，这张卡1回合只有1次不会被战斗破坏。'),
(67045174, 'Gemini Trap Hole', '二重落穴', '二重の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：再1次召唤状态的二重怪兽被战斗破坏时才能发动。对方场上的怪兽全部破坏。'),
(72305034, 'Geminize Lord Golknight', '重起士道-金骑士', '重起士道－ゴルドナイト', 'Gemini Monster', 'Warrior', 'EARTH', 4, 1500, 500, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡召唤·特殊召唤成功的场合才能发动。效果文本有「二重怪兽」记述的1张魔法·陷阱卡从卡组加入手卡。这个卡名的这个效果1回合只能使用1次。 ●这张卡变成机械族，攻击力上升500。'),
(52126602, 'Gen the Diamond Tiger', '虎菱之玄', '虎菱之玄', 'Effect Monster', 'Warrior', 'LIGHT', 3, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡·卡组把1只「毘龙之谦」在对方场上守备表示特殊召唤。 ②：这张卡用「毘龙之谦」的效果特殊召唤的场合发动。选自己1张手卡丢弃。 ③：自己·对方的战斗阶段结束时发动。场上的这张卡回到手卡。'),
(99000107, 'Gendo the Ascetic Monk', '修禅僧 元道', '修禅僧 ゲンドウ', 'Effect Monster', 'Spellcaster', 'WATER', 4, 300, 1800, '①：只要这张卡在怪兽区域存在，场上的表侧攻击表示怪兽不能把效果发动。 ②：守备表示的这张卡不会成为卡的效果的对象，不会被效果破坏。'),
(69247929, 'Gene-Warped Warwolf', '基因人狼', 'ジェネティック・ワーウルフ', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 2000, 100, '被遗传基因操作所强化的狼人。本来的和善之心已被完全破坏，肉体变成只为战斗而生。那个破坏力无可估量。'),
(720147, 'Generaider Boss Bite', '创王愤激', '王の憤激', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上的「王战」怪兽任意数量解放，以自己场上1只超量怪兽为对象才能发动。从自己的手卡·场上·墓地选解放数量的解放的怪兽以外的「王战」怪兽在作为对象的怪兽下面重叠作为超量素材。'),
(37931734, 'Generaider Boss Fight', '创王团战', '王の襲来', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的卡组·墓地选1张「王战」场地魔法卡发动。那之后，对方从卡组抽1张。'),
(1942635, 'Generaider Boss Loot', '创王报酬', '王の報酬', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有衍生物存在，对方不能选择「王战」效果怪兽作为攻击对象。 ②：「王战」效果怪兽被战斗破坏的场合发动。对方从卡组抽1张。'),
(75448086, 'Generaider Boss Quest', '创王试炼', '王の試練', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：手卡1只「王战」怪兽给对方观看，从卡组把「王战的试练」以外的最多2张「王战」魔法·陷阱卡加入手卡（同名卡最多1张）。那之后，给人观看的卡回到卡组最下面。'),
(64325438, 'Generaider Boss Room', '创王支配', '王の支配', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方连锁自己的「王战」卡的效果的发动把魔法·陷阱·怪兽的效果发动时，丢弃1张手卡才能发动。那个对方的效果变成「双方玩家各自从卡组抽1张」。'),
(38053381, 'Generaider Boss Stage', '创王关卡', '王の舞台', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，对方从卡组把卡加入手卡的场合才能发动。从卡组把1只「王战」怪兽守备表示特殊召唤。 ②：对方回合，自己对「王战」怪兽的特殊召唤成功的场合才能发动。在自己场上把「王战团队衍生物」（天使族·光·4星·攻/守1500）尽可能攻击表示特殊召唤。这衍生物在结束阶段破坏。'),
(53921056, 'General Gantala of the Ice Barrier', '冰结界的虎将 犍陀罗', '氷結界の虎将 ガンターラ', 'Effect Monster', 'Warrior', 'WATER', 7, 2700, 2000, '①：自己结束阶段，以「冰结界的虎将 健陀罗」以外的自己墓地1只「冰结界」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(9056100, 'General Grunard of the Ice Barrier', '冰结界的虎将 古尔纳德', '氷結界の虎将 グルナード', 'Effect Monster', 'Warrior', 'WATER', 8, 2800, 1000, '①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「冰结界」怪兽召唤。'),
(81275309, 'General Raiho of the Ice Barrier', '冰结界的虎将 雷奉', '氷結界の虎将 ライホウ', 'Effect Monster', 'Warrior', 'WATER', 6, 2100, 2300, '①：只要这张卡在怪兽区域存在，对方在场上发动的怪兽的效果的处理时，对方可以丢弃1张手卡。没丢弃的场合，那个效果无效化。'),
(81825063, 'General Wayne of the Ice Barrier', '冰结界的虎将 韦恩', '氷結界の虎将 ウェイン', 'Effect Monster', 'Warrior', 'WATER', 5, 2100, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上有怪兽存在，自己场上有「冰结界」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「冰结界」魔法·陷阱卡加入手卡。 ③：只要这张卡在怪兽区域存在，从场上送去对方墓地的魔法·陷阱卡不去墓地而除外。'),
(82735249, 'Generalprobe', '总彩排', 'ゲネラールプローベ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，每次「音响战士」卡持有的效果发动，给这张卡放置1个音响指示物。 ②：把自己场上3个音响指示物取除才能发动。从卡组把1只「音响战士」怪兽加入手卡。 ③：自己对「音响战士」怪兽的召唤·特殊召唤成功的场合才能发动。从卡组把1张「音响放大器」加入手卡。'),
(87890143, 'Generation Force', '世代之力', 'ジェネレーション・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有超量怪兽存在的场合才能发动。从卡组把1张「超量」卡加入手卡。'),
(85787173, 'Generation Next', '次一世代', 'ジェネレーション・ネクスト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己基本分比对方少的场合才能发动。从自己的卡组·墓地选持有双方基本分差的数值以下的攻击力的「元素英雄」怪兽、「栗子球」怪兽、「新空间侠」怪兽之内任意1只加入手卡或特殊召唤。这个回合，自己不能作那张卡以及那些同名卡的效果的发动。'),
(34460239, 'Generation Shift', '世代交替', 'ジェネレーション・チェンジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽破坏。那之后，从卡组把1张和破坏的卡同名的卡加入手卡。'),
(31038159, 'Genesis Dragon', '创世龙', '創世竜', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2200, 1800, '1回合1次，可以从手卡把1只龙族怪兽送去墓地，把自己墓地存在的1只龙族怪兽加入手卡。这张卡从场上送去墓地时，可以让自己墓地存在的龙族怪兽全部回到卡组。'),
(98147766, 'Genetic Woman', '基因女战士', 'ジェネティック・ウーマン', 'Effect Monster', 'Psychic', 'WIND', 4, 1700, 1200, '支付1000基本分，选择从游戏中除外的1只自己的念动力族怪兽发动。除外的那只怪兽加入手卡。这个效果1回合只能使用1次。'),
(66165755, 'Genex Ally Axel', 'A次代机・加速者', 'A・ジェネクス・アクセル', 'Synchro Monster', 'Machine', 'DARK', 8, 2600, 2000, '「次世代」调整＋调整以外的怪兽1只以上 ①：1回合1次，丢弃1张手卡，以自己墓地1只4星以下的机械族怪兽为对象才能发动。那只机械族怪兽特殊召唤。这个效果特殊召唤的怪兽攻击力直到回合结束时变成2倍，不能向对方直接攻击，自己结束阶段除外。'),
(91438994, 'Genex Ally Bellflame', 'A次代机・浴焰', 'A・ジェネクス・ベルフレイム', 'Effect Monster', 'Machine', 'DARK', 4, 1700, 1000, '①：每次从自己场上有怪兽被送去墓地，给这张卡放置1个次世代指示物。 ②：每次从对方墓地有卡被除外，给这张卡放置2个次世代指示物。 ③：这张卡的攻击力上升场上的次世代指示物数量×100。 ④：这张卡被战斗破坏送去墓地的场合发动。给与对方这张卡放置的次世代指示物数量×300伤害。'),
(64034255, 'Genex Ally Birdman', 'A次代机・鸟人', 'A・ジェネクス・バードマン', 'Tuner Monster', 'Machine', 'DARK', 3, 1400, 400, '①：让自己场上1只表侧表示怪兽回到手卡才能发动。这张卡从手卡特殊召唤。为这个效果发动而让风属性怪兽回到手卡的场合，这张卡的攻击力上升500。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(20127343, 'Genex Ally Changer', 'A次代机・转换者', 'A・ジェネクス・チェンジャー', 'Effect Monster', 'Machine', 'DARK', 3, 1200, 1800, '①：1回合1次，以场上1只表侧表示怪兽为对象，宣言1个属性才能发动。那只怪兽直到回合结束时变成宣言的属性。'),
(38049541, 'Genex Ally Chemistrer', 'A次代机・化学家', 'A・ジェネクス・ケミストリ', 'Tuner Monster', 'Machine', 'DARK', 2, 200, 500, '①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只「次世代」怪兽为对象，宣言1个属性才能发动。那只自己的「次世代」怪兽变成宣言的属性。'),
(27827903, 'Genex Ally Crusher', 'A次代机・粉碎机', 'A・ジェネクス・クラッシャー', 'Effect Monster', 'Machine', 'DARK', 4, 1000, 2000, '①：1回合1次，持有和这张卡相同属性的怪兽在自己场上召唤时，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(68450517, 'Genex Ally Duradark', 'A次代机・坚暗', 'A・ジェネクス・ドゥルダーク', 'Effect Monster', 'Machine', 'DARK', 4, 1800, 200, '①：1回合1次，以属性和这张卡相同的对方场上1只攻击表示怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。属性和这张卡相同的那只对方的攻击表示怪兽破坏。'),
(94622638, 'Genex Ally Powercell', 'A次代机・充能', 'A・ジェネクス・パワーコール', 'Effect Monster', 'Machine', 'DARK', 4, 1700, NULL, '①：只要这张卡在怪兽区域存在，持有和这张卡相同属性的自己场上的其他怪兽的攻击力上升500。'),
(63211608, 'Genex Ally Reliever', 'A次代机・复兴者', 'A・ジェネクス・リバイバー', 'Effect Monster', 'Machine', 'DARK', 5, 2200, 1000, '①：自己的卡的效果把对方的怪兽的效果·魔法·陷阱卡的发动无效的场合才能发动。这张卡从手卡特殊召唤。'),
(57238939, 'Genex Ally Remote', 'A次代机・远控', 'A・ジェネクス・リモート', 'Tuner Monster', 'Machine', 'DARK', 3, 500, 1800, '①：1回合1次，以场上1只调整为对象才能发动。那只怪兽的卡名直到结束阶段当作「次世代控制员」使用。'),
(83500096, 'Genex Ally Solid', 'A次代机・涌刃', 'A・ジェネクス・ソリッド', 'Effect Monster', 'Machine', 'DARK', 2, 500, 1200, '①：1回合1次，把自己场上1只表侧表示的水属性「次世代」怪兽送去墓地才能发动。自己抽2张。'),
(17760003, 'Genex Ally Triarm', 'A次代机・三重武装', 'A・ジェネクス・トライアーム', 'Synchro Monster', 'Machine', 'DARK', 6, 2400, 1600, '「次世代控制员」＋调整以外的怪兽1只以上 ①：1回合1次，可以丢弃1张手卡，从作为这张卡的同调素材的除调整以外的怪兽属性的以下效果选择1个发动。 ●风：对方手卡随机1张送去墓地。 ●水：以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ●暗：以场上1只光属性怪兽为对象才能发动。那只光属性怪兽破坏，自己抽1张。'),
(52709508, 'Genex Ally Triforce', 'A次代机・三重武力', 'A・ジェネクス・トライフォース', 'Synchro Monster', 'Machine', 'DARK', 7, 2500, 2100, '「次世代」调整＋调整以外的怪兽1只以上 ①：这张卡得到作为这张卡的同调素材的除调整以外的怪兽属性的以下效果。 ●地：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ●炎：这张卡战斗破坏怪兽的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。 ●光：1回合1次，以自己墓地1只光属性怪兽为对象才能发动。那只光属性怪兽里侧守备表示特殊召唤。'),
(56511382, 'Genex Ally Volcannon', 'A次代机・火炮', 'A・ジェネクス・ボルキャノン', 'Effect Monster', 'Machine', 'DARK', 4, 1700, 600, '①：1回合1次，把自己场上1只表侧表示的炎属性「次世代」怪兽送去墓地，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽破坏，给与对方那个等级×400伤害。'),
(93211836, 'Genex Army', '军用次代机', 'アーミー・ジェネクス', 'Effect Monster', 'Machine', 'EARTH', 6, 2300, 1300, '①：这张卡把「次世代」怪兽解放作上级召唤时，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(24432029, 'Genex Blastfan', '次代机・鼓风', 'ジェネクス・ブラスト', 'Effect Monster', 'Spellcaster', 'WIND', 4, 1600, 1300, '①：这张卡特殊召唤时才能发动。从卡组把1只暗属性「次世代」怪兽加入手卡。'),
(68505803, 'Genex Controller', '次代机・控制者', 'ジェネクス・コントローラー', 'Normal Tuner Monster', 'Machine', 'DARK', 3, 1400, 1200, '与同伴们能心意相通的少数次世代一员。可是能控制各种元素力量的哟。'),
(89211486, 'Genex Doctor', '次代机・博士', 'ジェネクス・ドクター', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1500, 1000, '①：把自己场上1只表侧表示的「次世代控制员」解放，以场上1张卡为对象才能发动。那张卡破坏。'),
(53944920, 'Genex Furnace', '次代机・热炉', 'ジェネクス・ヒート', 'Effect Monster', 'Pyro', 'FIRE', 5, 2000, 1300, '①：自己场上有「次世代控制员」存在的场合，这张卡可以不用解放作召唤。'),
(89333528, 'Genex Gaia', '次代机・盖亚', 'ジェネクス・ガイア', 'Effect Monster', 'Rock', 'EARTH', 3, 1000, 1900, '①：场上的这张卡被战斗·效果破坏的场合，可以作为代替把自己场上1只「次世代控制员」破坏。'),
(19182751, 'Genex Neutron', '次代机・中子', 'ジェネクス・ニュートロン', 'Effect Monster', 'Machine', 'LIGHT', 4, 1800, 1200, '①：这张卡召唤的回合的结束阶段才能发动。从卡组把1只机械族调整加入手卡。'),
(30399511, 'Genex Power Planner', '次代机・动力员', 'ジェネクス・パワー・プランナー', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, 300, 200, '①：这张卡召唤时才能发动。从卡组把1只3星「次世代」效果怪兽加入手卡。'),
(51827737, 'Genex Recycled', '再生次代机', 'リサイクル・ジェネクス', 'Tuner Monster', 'Machine', 'DARK', 1, 200, 400, '①：1回合1次，以自己墓地1只「次世代」怪兽为对象才能发动。这张卡直到结束阶段当作和作为对象的怪兽同名卡使用。'),
(67483216, 'Genex Searcher', '次代机・搜索员', 'ジェネクス・サーチャー', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 400, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的「次世代」怪兽攻击表示特殊召唤。'),
(15605085, 'Genex Solar', '太阳能次代机', 'ソーラー・ジェネクス', 'Effect Monster', 'Machine', 'LIGHT', 7, 2500, 1500, '这张卡可以把1只「次世代」怪兽解放表侧表示上级召唤。 ①：这张卡在怪兽区域存在的状态，每次自己场上的表侧表示的「次世代」怪兽被送去墓地发动。给与对方500伤害。'),
(16828633, 'Genex Spare', '后备次代机', 'スペア・ジェネクス', 'Tuner Monster', 'Machine', 'DARK', 3, 800, 1200, '①：1回合1次，自己场上有其他的「次世代」怪兽存在的场合才能发动。这张卡的卡名直到结束阶段当作「次世代控制员」使用。'),
(52222372, 'Genex Turbine', '涡轮次代机', 'タービン・ジェネクス', 'Effect Monster', 'Machine', 'EARTH', 4, 1400, 1300, '①：只要这张卡在怪兽区域存在，自己场上的「次世代」怪兽的攻击力上升400。'),
(4904812, 'Genex Undine', '次代机・水精灵', 'ジェネクス・ウンディーネ', 'Effect Monster', 'Aqua', 'WATER', 3, 1200, 600, '①：这张卡召唤时，从卡组把1只水属性怪兽送去墓地才能发动。从卡组把1只「次世代控制员」加入手卡。'),
(93882364, 'Genex Worker', '次代机・工作员', 'ジェネクス・ワーカー', 'Effect Monster', 'Machine', 'WIND', 3, 1200, 1200, '①：把这张卡解放才能发动。从手卡把1只「次世代」怪兽特殊召唤。'),
(49370026, 'Genin', '戏法师', 'ジャグラー', 'Normal Monster', 'Spellcaster', 'LIGHT', 3, 600, 900, '使用像戏法般的魔法打倒对方。也会放出鸽子攻击。'),
(7656689, 'Genni, the Maid of Endymion', '恩底弥翁的侍女 杰妮', 'エンディミオンの侍女ジェニー', 'Effect Monster', 'Spellcaster', 'WIND', 1, 300, 500, '这个卡名在规则上也当作「魔女术」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有魔法师族怪兽存在的场合才能发动。这张卡特殊召唤。 ②：自己·对方的主要阶段，以自己场上1只魔法师族怪兽为对象才能发动。那只怪兽除外，从卡组把「恩底弥翁的侍女 杰妮」以外的1只「魔女术」怪兽特殊召唤。'),
(42155488, 'Genomix Fighter', '基因组斗士', 'ジェノミックス・ファイター', 'Tuner Monster', 'Psychic', 'WIND', 6, 2200, 1100, '这张卡可以不用解放作召唤。这个方法召唤的这张卡的等级变成3星，原本攻击力变成一半。此外，1回合1次，宣言1个种族才能发动。这个回合把这张卡作为同调素材的场合，包含这张卡的那一组同调素材怪兽当作宣言的种族使用。这个效果发动过的回合，自己不能把宣言的种族以外的怪兽召唤·特殊召唤。'),
(56499179, 'Genro Ryu-Ge Hakva', '幻朧龙华－霸轮巴王', '幻朧竜華－霸巴', 'Effect Monster', 'Wyrm', 'WIND', 10, 3000, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：把这张卡从手卡除外才能发动。从卡组把1张「登龙华幻胧门」加入手卡。 ②：这张卡是除外状态，怪兽被表侧除外的场合，若「幻胧龙华-霸巴」以外的除外状态的怪兽2只以上存在则能发动。这张卡特殊召唤。 ③：让自己场上1张表侧表示的「登龙华幻胧门」回到卡组最下面才能发动。「幻胧龙华-霸巴」以外的自己的卡组·墓地·除外状态的1张「龙华」卡加入手卡。'),
(77895328, 'Genta, Gateman of Dark World', '暗黑界的门番 真塔', '暗黒界の門番 ゼンタ', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1800, '自己对「暗黑界的门番 真塔」1回合只能有1次特殊召唤。 ①：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「暗黑界之门」加入手卡。 ②：这张卡被除外的场合，若自己场上有「暗黑界」卡存在则能发动。这张卡特殊召唤。'),
(54635862, 'Gentlemander', '美西螈绅士', 'ジェントルーパー', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1200, 1000, '对方怪兽的攻击宣言时，这张卡可以从手卡特殊召唤。只要这张卡在场上表侧表示存在，对方不能向其他怪兽攻击。'),
(33972299, 'Geo Genex', '地能次代机', 'ジオ・ジェネクス', 'Synchro Monster', 'Machine', 'EARTH', 6, 1800, 2800, '「次世代控制员」＋调整以外的地属性怪兽1只以上 ①：1回合1次，自己场上有4星以下的「次世代」怪兽存在的场合才能发动。这张卡的原本攻击力和原本守备力直到回合结束时交换。这个效果直到变成自己场上没有4星以下的「次世代」怪兽存在为止适用。'),
(56704140, 'Geomancer of the Ice Barrier', '冰结界的风水师', '氷結界の風水師', 'Tuner Monster', 'Spellcaster', 'WATER', 3, 800, 1200, '①：只在这张卡表侧表示存在才有1次，丢弃1张手卡，宣言1个属性才能发动。宣言的属性的怪兽不能选择表侧表示的这张卡作为攻击对象。'),
(42632209, 'Geomathmech Final Sigma', '炎斩机最终西格玛', '炎斬機ファイナルシグマ', 'Synchro Monster', 'Cyberse', 'FIRE', 12, 3000, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡只要在额外怪兽区域存在，不受「斩机」卡以外的卡的效果影响。 ②：额外怪兽区域的这张卡用和对方怪兽的战斗给与对方的战斗伤害变成2倍。 ③：这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1张「斩机」卡加入手卡。'),
(15248594, 'Geomathmech Magma', '炎斩机玛格玛', '炎斬機マグマ', 'Synchro Tuner Monster', 'Cyberse', 'FIRE', 8, 2500, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡战斗破坏怪兽时，以对方场上最多2张卡为对象才能发动。那些卡破坏。 ②：这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1张「斩机」魔法·陷阱卡加入手卡。'),
(52119435, 'Geonator Transverser', '转晶之石装调整者', '転晶のコーディネラル', 'Link Monster', 'Rock', 'EARTH', NULL, 1200, NULL, '效果怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：连接状态的这张卡以及这张卡所连接区的怪兽不会被对方的效果破坏。 ②：这张卡所连接区有怪兽2只存在的场合才能发动。那2只怪兽的控制权交换。'),
(32991027, 'Georgius, Swordman of the Ice Barrier', '冰结界的剑士 格奥鲁吉亚斯', '氷結界の剣士 ゲオルギアス', 'Tuner Monster', 'Winged Beast', 'WATER', 6, 2000, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「冰结界」怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从自己的手卡·墓地把1只5星以下的「冰结界」怪兽特殊召唤。 ③：只要自己场上有其他的「冰结界」怪兽存在，对方不能把墓地的怪兽的效果发动。'),
(59490397, 'Gergonne''s End', '热尔岗终焉', 'ジェルゴンヌの終焉', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「廷达魔三角」连接怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽不会被战斗·效果破坏，不会成为对方的效果的对象。 ②：1回合1次，装备怪兽的全部连接标记的所向点有怪兽存在的场合才能发动。那些怪兽和这张卡全部破坏。全部破坏的场合，给与对方这张卡装备过的怪兽的攻击力数值的伤害。'),
(28373620, 'Geri the Runick Fangs', '神碑之牙 基利', '神碑の牙ゲーリ', 'Fusion Monster', 'Beast', 'DARK', 4, NULL, 1000, '「神碑」怪兽×2 ①：这张卡从额外卡组的特殊召唤成功的场合，以速攻魔法卡以外的自己墓地1张「神碑」魔法卡为对象才能发动。那张卡加入手卡。 ②：场上的这张卡不会被效果破坏。 ③：这张卡被战斗破坏时，以场上1张卡为对象才能发动。那张卡破坏。'),
(24668830, 'Germ Infection', '细菌感染', '細菌感染', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族以外的怪兽装备可能。装备怪兽的攻击力在每次的自己的准备阶段攻击力下降300。'),
(77936940, 'Gernia', '杰尔尼亚', 'ゲルニア', 'Effect Monster', 'Zombie', 'DARK', 4, 1300, 1200, '①：场上的表侧表示的这张卡被对方的效果破坏送去墓地的场合，下次的自己准备阶段发动。这张卡从墓地特殊召唤。'),
(22373487, 'Get Out!', '滚・粗・去！', 'ゲット・アウト！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以从额外卡组特殊召唤的对方场上2只怪兽为对象才能发动。那些怪兽回到持有者卡组。'),
(111000561, 'Get Your Game On!', NULL, NULL, 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(21887179, 'Getsu Fuhma', '月风魔', '月風魔', 'Effect Monster', 'Warrior', 'DARK', 4, 1700, 1200, '与这张卡进行战斗的恶魔族·不死族怪兽在伤害步骤终了时被破坏。'),
(84046493, 'Ghost Beef', '鬼牛肉', 'ゴースト・ビーフ', 'Pendulum Normal Monster', 'Beast', 'DARK', 7, 2000, 1000, '属于美食家的牛类幽灵。对最爱吃的烤牛肉特别着迷，今天也是为与新味道相遇而一边满怀喜悦一边游荡于现世。'),
(73642296, 'Ghost Belle & Haunted Mansion', '屋敷童子', '屋敷わらし', 'Tuner Monster', 'Zombie', 'EARTH', 3, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：包含以下其中任意种效果的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个发动无效。 ●从墓地把卡加入手卡·卡组·额外卡组的效果 ●从墓地把怪兽特殊召唤的效果 ●从墓地把卡除外的效果'),
(15419596, 'Ghost Bird of Bewitchment', '魅幽鸟', '魅幽鳥', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1300, 1500, '①：这张卡只要在主要怪兽区域存在，得到那个位置的以下效果。 ●左端：这张卡的攻击力·守备力上升1000。 ●右端：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ●中央：这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ●那以外：和这张卡相同纵列的怪兽不能把效果发动。'),
(23379054, 'Ghost Charon, the Underworld Boatman', '劫火之舟守 幽灵卡戎', '劫火の舟守 ゴースト・カロン', 'Tuner Monster', 'Zombie', 'DARK', 2, 500, NULL, '「劫火之舟守 幽鬼冥船夫」的效果1回合只能使用1次，这个效果发动的回合，自己不是龙族怪兽不能特殊召唤。 ①：对方场上有怪兽存在，自己场上没有这张卡以外的怪兽存在的场合，以自己墓地1只融合怪兽为对象才能发动。墓地的那只怪兽和场上的这张卡除外，把持有和那2只的等级合计相同等级的1只龙族同调怪兽从额外卡组特殊召唤。'),
(44663232, 'Ghost Fairy Elfobia', '异怪妖精 艾尔佛比亚', '異怪の妖精 エルフォビア', 'Effect Monster', 'Psychic', 'WIND', 3, 900, 500, '1回合1次，把手卡1只风属性怪兽给对方观看才能发动。直到下次的对方的主要阶段1结束时，双方玩家不能把比给人观看的怪兽等级高的怪兽的效果发动。'),
(35705817, 'Ghost Fusion', '幽合－幽灵结合', '幽合－ゴースト・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，融合素材怪兽必须全部是不死族怪兽。自己基本分比对方少的场合，自己的手卡·卡组·墓地的不死族怪兽也能有最多1只除外作为融合素材。'),
(59965151, 'Ghost Gardna', '死体守卫者', 'デッド・ガードナー', 'Effect Monster', 'Warrior', 'DARK', 4, NULL, 1900, '自己场上表侧表示存在的怪兽被选择作为攻击对象时，可以让攻击对象改变为这张卡。这张卡被破坏送去墓地时，对方场上表侧表示存在的1只怪兽的攻击力直到结束阶段时下降1000。'),
(13386503, 'Ghost Knight of Jackal', '胡狼灵骑士', 'ジャッカルの霊騎士', 'Effect Monster', 'Beast-Warrior', 'EARTH', 5, 1700, 1600, '可以将1只被这张卡战斗破坏并被送去墓地的对方怪兽以表侧守备表示特殊召唤到自己场上。'),
(64104037, 'Ghost Lancer, the Underworld Spearman', '劫火之枪术士 幽灵枪兵', '劫火の槍術士 ゴースト・ランサー', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, NULL, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡不会被和从额外卡组特殊召唤的怪兽以外的怪兽的战斗破坏。 ③：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(62219643, 'Ghost Meets Girl - A Masterful Mayakashi Shiranui Saga', '逢华妖丽谭－魔妖不知火语', '逢華妖麗譚－魔妖不知火語', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把自己场上1只「魔妖」同调·连接怪兽或者「不知火」同调·连接怪兽解放才能发动。这个回合，双方不能从手卡·卡组·额外卡组把怪兽特殊召唤。 ②：把墓地的这张卡除外，以除外的1只自己的不死族怪兽为对象才能发动。那只怪兽回到墓地。'),
(83266006, 'Ghost Meets Girl - A Mayakashi''s Manuscript', '逢华妖丽谭－魔妖语', '逢華妖麗譚－魔妖語', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，以自己场上1只不死族同调怪兽为对象才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选和作为对象的怪兽相同属性的1只不死族怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段除外。这张卡的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。'),
(13965201, 'Ghost Meets Girl - A Shiranui''s Story', '逢华妖丽谭－不知火语', '逢華妖麗譚－不知火語', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上有怪兽存在的场合，从手卡丢弃1只不死族怪兽才能发动。从自己的卡组·墓地选和丢弃的怪兽卡名不同的1只「不知火」怪兽特殊召唤。这张卡的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。'),
(52038441, 'Ghost Mourner & Moonlit Chill', '朔夜时雨', '朔夜しぐれ', 'Tuner Monster', 'Zombie', 'WIND', 3, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：对方把怪兽表侧表示特殊召唤的场合，把这张卡从手卡丢弃，以那些表侧表示怪兽之内的1只为对象才能发动。那只怪兽的效果直到回合结束时无效化，这个回合中作为对象的表侧表示怪兽从场上离开时那个控制者受到作为对象的怪兽的原本攻击力数值的伤害。'),
(67113830, 'Ghost of a Grudge', '墓地墓地的怨恨', '墓地墓地の恨み', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方墓地的卡是8张以上的场合才能发动。对方场上的全部怪兽的攻击力变成0。'),
(59438930, 'Ghost Ogre & Snow Rabbit', '幽鬼兔', '幽鬼うさぎ', 'Tuner Monster', 'Psychic', 'LIGHT', 3, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：场上的怪兽的效果发动时或者场上的已是表侧表示存在的魔法·陷阱卡的效果发动时，把手卡·场上的这张卡送去墓地才能发动。场上的那张卡破坏。'),
(62015408, 'Ghost Reaper & Winter Cherries', '浮幽樱', '浮幽さくら', 'Tuner Monster', 'Zombie', 'DARK', 3, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，对方场上的怪兽数量比自己场上的怪兽多的场合，把这张卡从手卡丢弃才能发动。选自己的额外卡组1张卡给双方确认。那之后，把对方的额外卡组确认，有选的卡的同名卡的场合，那些对方的同名卡全部除外。'),
(33347467, 'Ghost Ship', '灵魂护送船', '霊魂の護送船', 'Effect Monster', 'Fiend', 'LIGHT', 5, 1900, 1000, '这张卡不能通常召唤。把自己墓地存在的1只光属性怪兽从游戏中除外的场合可以特殊召唤。'),
(60643553, 'Ghost Sister & Spooky Dogwood', '儚无水木', '儚無みずき', 'Tuner Monster', 'Zombie', 'WATER', 3, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃才能发动。这个回合中，以下效果适用。 ●每次对方在主要阶段以及战斗阶段把效果怪兽特殊召唤，自己回复那些怪兽的攻击力数值的基本分。这个效果没让自己基本分回复的场合，结束阶段让自己基本分变成一半。'),
(99370594, 'Ghost Sleeper, the Underworld Princess', '劫火之长眠姬 幽灵睡美人', '劫火の眠り姫 ゴースト・スリーパー', 'Effect Monster', 'Zombie', 'DARK', 3, 1300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合才能发动。从卡组把1张「幽合-幽鬼融合」加入手卡。 ②：把墓地的这张卡除外，丢弃1张手卡，以除外的1只自己的4星以上的不死族怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(35268888, 'Ghost Token', '伤害转化', 'ダメージ・トランスレーション', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(61103515, 'Ghost Wyvern, the Underworld Dragon', '劫火之翼龙 幽灵飞龙', '劫火の翼竜 ゴースト・ワイバーン', 'Effect Monster', 'Zombie', 'DARK', 4, 1700, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「幽合-幽鬼融合」加入手卡。 ②：这张卡被除外的回合的结束阶段才能发动。从卡组选1只2星以下的不死族调整加入手卡或送去墓地。'),
(75367227, 'Ghostrick Alucard', '鬼计・阿尔卡德', 'ゴーストリック・アルカード', 'XYZ Monster', 'Zombie', 'DARK', 3, 1800, 1600, '3星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方不能选择其他的「鬼计」怪兽以及里侧守备表示怪兽作为攻击对象。 ②：把这张卡1个超量素材取除，以对方场上盖放的1张卡为对象才能发动。那张盖放的对方的卡破坏。 ③：这张卡被送去墓地的场合，以这张卡以外的自己墓地1张「鬼计」卡为对象才能发动。那张卡加入手卡。'),
(53334641, 'Ghostrick Angel of Mischief', '鬼计的惰天使', 'ゴーストリックの駄天使', 'XYZ Monster', 'Fairy', 'DARK', 4, 2000, 2500, '4星怪兽×2 这张卡也能在「鬼计惰天使」以外的自己场上的「鬼计」超量怪兽上面重叠来超量召唤。这张卡持有的超量素材数量变成10时，自己决斗胜利。 ①：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1张「鬼计」魔法·陷阱卡加入手卡。 ②：1回合1次，自己主要阶段才能发动。把手卡1张「鬼计」卡在这张卡下面重叠作为超量素材。'),
(80802524, 'Ghostrick Break', '鬼计心碎', 'ゴーストリック・ブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的「鬼计」怪兽1只被战斗或者对方的效果破坏送去自己墓地时，以和破坏的那只怪兽卡名不同的自己墓地2只「鬼计」怪兽为对象才能发动。那些怪兽里侧守备表示特殊召唤。'),
(46925518, 'Ghostrick Doll', '鬼计的人偶', 'ゴーストリックの人形', 'Effect Monster', 'Spellcaster', 'DARK', 2, 300, 1200, '自己场上有「鬼计」怪兽存在的场合才能让这张卡表侧表示召唤。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转的场合发动。这个回合的结束阶段，场上的表侧表示怪兽全部变成里侧守备表示。那之后，可以把持有这个效果变成里侧守备表示的怪兽数量以下的等级的1只「鬼计」怪兽从卡组里侧守备表示特殊召唤。'),
(46895036, 'Ghostrick Dullahan', '鬼计・无头骑士', 'ゴーストリック・デュラハン', 'XYZ Monster', 'Fiend', 'DARK', 1, 1000, NULL, '1星怪兽×2 ①：这张卡的攻击力上升自己场上的「鬼计」卡数量×200。 ②：1回合1次，把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成一半。这个效果在对方回合也能发动。 ③：这张卡被送去墓地的场合，以这张卡以外的自己墓地1张「鬼计」卡为对象才能发动。那张卡加入手卡。'),
(36239585, 'Ghostrick Fairy', '鬼计的妖精', 'ゴーストリックの妖精', 'Effect Monster', 'Spellcaster', 'DARK', 2, 900, 1000, '自己场上有「鬼计」怪兽存在的场合才能让这张卡表侧表示召唤。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转时，以自己墓地1张「鬼计」卡为对象才能发动。那张卡在自己场上盖放。那张卡从场上离开的场合除外。那之后，可以选最多有自己场上盖放的卡数量的对方场上的表侧表示怪兽变成里侧守备表示。'),
(35871958, 'Ghostrick Festival', '鬼计嘉年华', 'ゴーストリック・フェスティバル', 'Link Monster', 'Spellcaster', 'DARK', NULL, NULL, NULL, '连接怪兽以外的「鬼计」怪兽1只 这张卡连接召唤的场合，自己场上的里侧表示的「鬼计」怪兽也能作为连接素材。这个卡名的②的效果1回合只能使用1次。 ①：只要场地区域有「鬼计」卡存在，自己的「鬼计」怪兽可以直接攻击。 ②：对方怪兽的攻击宣言时，把这张卡解放才能发动。从卡组把1只「鬼计」怪兽里侧守备表示特殊召唤。'),
(85463083, 'Ghostrick Ghoul', '鬼计食尸鬼', 'ゴーストリック・グール', 'Effect Monster', 'Zombie', 'DARK', 3, 1100, 1200, '自己场上有「鬼计」怪兽存在的场合才能让这张卡表侧表示召唤。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：自己主要阶段1有1次，以自己场上1只「鬼计」怪兽为对象才能发动。那只怪兽的攻击力直到下次的对方回合的结束时变成场上的「鬼计」怪兽的原本攻击力合计数值，这个回合作为对象的怪兽以外的怪兽不能攻击。'),
(61318483, 'Ghostrick Jackfrost', '鬼计・霜精', 'ゴーストリック・フロスト', 'Effect Monster', 'Fiend', 'DARK', 1, 800, 100, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，对方怪兽的直接攻击宣言时才能发动。那只对方怪兽变成里侧守备表示，这张卡从手卡里侧守备表示特殊召唤。'),
(80885284, 'Ghostrick Jiangshi', '鬼计・跳尸', 'ゴーストリック・キョンシー', 'Effect Monster', 'Zombie', 'DARK', 3, 400, 1800, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，这张卡反转时，可以把持有自己场上的名字带有「鬼计」的怪兽数量以下的等级的1只名字带有「鬼计」的怪兽从卡组加入手卡。「鬼计僵尸」的这个效果1回合只能使用1次。'),
(54512827, 'Ghostrick Lantern', '鬼计・南瓜灯', 'ゴーストリック・ランタン', 'Effect Monster', 'Fiend', 'DARK', 1, 800, NULL, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，对方怪兽的直接攻击宣言时或者自己场上的名字带有「鬼计」的怪兽被选择作为攻击对象时才能发动。那次攻击无效，这张卡从手卡里侧守备表示特殊召唤。'),
(99795159, 'Ghostrick Mansion', '鬼计屋', 'ゴーストリック・ハウス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，双方怪兽不能向里侧守备表示怪兽攻击，可以在对方场上的怪兽只有里侧守备表示怪兽的场合向对方直接攻击。 ②：只要这张卡在场地区域存在，双方受到的效果伤害变成一半，「鬼计」怪兽以外的怪兽给与玩家的战斗伤害变成一半。'),
(98707192, 'Ghostrick Mary', '鬼计・玛丽', 'ゴーストリック・マリー', 'Effect Monster', 'Fiend', 'DARK', 1, 100, 1600, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，战斗或者卡的效果让自己受到伤害时，把这张卡从手卡丢弃才能发动。从卡组把1只名字带有「鬼计」的怪兽里侧守备表示特殊召唤。「鬼计妖魔·玛丽」的这个效果1回合只能使用1次。'),
(97584500, 'Ghostrick Mummy', '鬼计・木乃伊', 'ゴーストリック・マミー', 'Effect Monster', 'Zombie', 'DARK', 3, 1500, NULL, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，只要这张卡在场上表侧表示存在，自己在通常召唤外加上只有1次可以把1只名字带有「鬼计」的怪兽召唤。只要这张卡在场上表侧表示存在，自己不能把暗属性以外的怪兽特殊召唤。'),
(7617062, 'Ghostrick Museum', '鬼计博物馆', 'ゴーストリック・ミュージアム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，名字带有「鬼计」的怪兽以外的自己场上的怪兽不能攻击，双方场上的怪兽不能向里侧守备表示怪兽攻击，可以在对方场上的怪兽只有里侧守备表示怪兽的场合直接攻击对方玩家。此外，给与玩家战斗伤害的怪兽在伤害步骤结束时变成里侧守备表示。'),
(24101897, 'Ghostrick Nekomusume', '鬼计的猫娘', 'ゴーストリックの猫娘', 'Effect Monster', 'Spellcaster', 'DARK', 2, 400, 900, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，只要场上有这张卡以外的名字带有「鬼计」的怪兽存在，4星以上的怪兽召唤·特殊召唤成功时，那些怪兽变成里侧守备表示。'),
(85827713, 'Ghostrick Night', '鬼计之夜', 'ゴーストリック・ナイト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要场上有名字带有「鬼计」的怪兽存在，对方场上的怪兽不能反转召唤。此外，这张卡被对方破坏送去墓地时发动。这个回合对方不能攻击宣言。'),
(27170599, 'Ghostrick or Treat', '不给糖就搞鬼计', 'ゴーストリック・オア・トリート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「鬼计」场地魔法卡或者「鬼计」连接怪兽存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。对方可以支付2000基本分。那个场合，这张卡的效果变成「发动后这张卡不送去墓地，直接盖放」。没支付的场合，这个回合，那只表侧表示怪兽不能攻击，效果无效化，结束阶段变成里侧守备表示。'),
(29400787, 'Ghostrick Parade', '鬼计游行', 'ゴーストリック・パレード', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方场上的怪兽不能向里侧守备表示怪兽攻击，可以在对方场上的怪兽只有里侧守备表示怪兽的场合直接攻击对方玩家。此外，对方怪兽的直接攻击宣言时，可以从自己卡组把1张名字带有「鬼计」的卡加入手卡。只要这张卡在场上存在，对方玩家受到的全部伤害变成0。'),
(61818176, 'Ghostrick Renovation', '鬼计翻修', 'ゴーストリック・リフォーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1张「鬼计」场地魔法卡为对象才能发动。那张卡回到持有者手卡。那之后，可以从手卡·卡组把1张场地魔法卡发动。 ②：把墓地的这张卡除外，以自己场上1只「鬼计」超量怪兽为对象才能发动。和那只自己怪兽卡名不同的1只「鬼计」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(86516889, 'Ghostrick Scare', '鬼计恐慌', 'ゴーストリック・パニック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上里侧守备表示存在的怪兽任意数量才能发动。选择的怪兽变成表侧守备表示，选最多有那之中的名字带有「鬼计」的怪兽数量的对方场上表侧表示存在的怪兽变成里侧守备表示。'),
(69809989, 'Ghostrick Shot', '鬼计弹射', 'ゴーストリック・ショット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地选1只「鬼计」怪兽特殊召唤。那之后，可以选自己场上1只里侧表示的「鬼计」怪兽变成表侧攻击表示。 ②：把墓地的这张卡除外，以自己场上1只「鬼计」超量怪兽为对象才能发动。从自己墓地选1张「鬼计」卡在作为对象的怪兽下面重叠作为超量素材。'),
(64804316, 'Ghostrick Siren', '鬼计・塞壬', 'ゴーストリック・セイレーン', 'Effect Monster', 'Fairy', 'DARK', 4, 800, 1500, '自己场上有「鬼计」怪兽存在的场合才能让这张卡表侧表示召唤。 ①：这张卡召唤·反转的场合发动。从自己卡组上面把2张卡送去墓地。那之中有「鬼计」卡的场合，可以再从以下效果选1个适用。 ●从卡组把1张「鬼计」魔法·陷阱卡加入手卡。 ●选对方场上1只效果怪兽变成里侧守备表示。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。'),
(51196805, 'Ghostrick Skeleton', '鬼计骷髅', 'ゴーストリック・スケルトン', 'Effect Monster', 'Zombie', 'DARK', 3, 1200, 1100, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，这张卡反转时，把最多有自己场上的名字带有「鬼计」的怪兽数量的卡从对方卡组上面里侧表示除外。「鬼计骷髅」的这个效果1回合只能使用1次。'),
(32224143, 'Ghostrick Socuteboss', '鬼计・梦魔', 'ゴーストリック・サキュバス', 'XYZ Monster', 'Spellcaster', 'DARK', 2, 1400, 1200, '2星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择持有场上的名字带有「鬼计」的怪兽的攻击力合计以下的攻击力的场上1只怪兽才能发动。选择的怪兽破坏，只要自己场上有名字带有「鬼计」的怪兽存在，那个怪兽卡区域不能使用。此外，自己场上有这张卡以外的名字带有「鬼计」的怪兽存在的场合，对方不能把这张卡作为攻击对象。'),
(81907872, 'Ghostrick Specter', '鬼计・幽灵', 'ゴーストリック・スペクター', 'Effect Monster', 'Fiend', 'DARK', 1, 600, NULL, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，名字带有「鬼计」的怪兽被对方的卡的效果或者对方怪兽的攻击破坏送去自己墓地时才能发动。这张卡从手卡里侧守备表示特殊召唤，从卡组抽1张卡。'),
(16279989, 'Ghostrick Stein', '鬼计・科学怪人', 'ゴーストリック・シュタイン', 'Effect Monster', 'Zombie', 'DARK', 3, 1600, NULL, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，这张卡给与对方基本分战斗伤害时，可以从卡组把1张名字带有「鬼计」的魔法·陷阱卡加入手卡。「鬼计科学怪人」的这个效果1回合只能使用1次。'),
(50527144, 'Ghostrick Vanish', '鬼计匿影', 'ゴーストリック・アウト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1只名字带有「鬼计」的怪兽给对方观看才能发动。这个回合，自己场上的名字带有「鬼计」的卡以及里侧守备表示存在的怪兽不会成为卡的效果的对象，不会被卡的效果破坏。'),
(72913666, 'Ghostrick Warwolf', '鬼计狼人', 'ゴーストリック・ワーウルフ', 'Effect Monster', 'Zombie', 'DARK', 3, 1400, 1500, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，这张卡反转时，给与对方基本分场上盖放的卡数量×100的数值的伤害。「鬼计狼人」的这个效果1回合只能使用1次。'),
(27491571, 'Ghostrick Witch', '鬼计的魔女', 'ゴーストリックの魔女', 'Effect Monster', 'Spellcaster', 'DARK', 2, 1200, 200, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，1回合1次，选择对方场上表侧表示存在的1只怪兽才能发动。选择的怪兽变成里侧守备表示。'),
(84472026, 'Ghostrick Yeti', '鬼计雪人', 'ゴーストリック・イエティ', 'Effect Monster', 'Zombie', 'DARK', 3, 300, 2000, '自己场上有「鬼计」怪兽存在的场合才能让这张卡表侧表示召唤。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转时，以场上1只「鬼计」怪兽为对象才能发动。那只怪兽在这个回合不会被战斗·效果破坏。'),
(54490275, 'Ghostrick Yuki-onna', '鬼计的雪女', 'ゴーストリックの雪女', 'Effect Monster', 'Spellcaster', 'DARK', 2, 1000, 800, '自己场上有名字带有「鬼计」的怪兽存在的场合才能让这张卡表侧表示召唤。这张卡1回合只有1次可以变成里侧守备表示。此外，这张卡被战斗破坏送去墓地时才能发动。让把这张卡破坏的怪兽变成里侧守备表示，不能把表示形式变更。'),
(37055344, 'Ghostrick-Go-Round', '鬼计天旋地转', 'ゴーストリック・ロールシフト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，战斗阶段中可以从以下效果选择1个发动。 ●选择自己场上1只名字带有「鬼计」的怪兽变成里侧守备表示，选对方场上里侧守备表示存在的1只怪兽变成表侧攻击表示。 ●选择自己场上里侧守备表示存在的1只怪兽变成表侧攻击表示，那是名字带有「鬼计」的怪兽的场合，选对方场上表侧表示存在的1只怪兽变成里侧守备表示。'),
(51099515, 'Ghosts From the Past', '恐击', '恐撃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己墓地2只怪兽除外，以场上1只表侧攻击表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成0。'),
(45792753, 'Ghoti Chain', '游魊链', 'ゴーティス・チェイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示的鱼族怪兽除外才能发动。原本卡名和为这张卡发动而除外的怪兽不同的1只「魊影」怪兽从自己的手卡·卡组·墓地·除外状态特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(38409239, 'Ghoti Cosmos', '游魊宇宙', 'ゴーティス・コスモス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：除外状态的鱼族怪兽数量的以下效果各适用。 ●1只以上：这个回合，自己的鱼族怪兽不会被战斗破坏。 ●4只以上：这个回合，自己场上的鱼族怪兽的效果的发动以及那些发动的效果不会被无效化。 ●8只以上：从额外卡组把1只鱼族同调怪兽当作同调召唤作特殊召唤。'),
(65898344, 'Ghoti Fury', '游魊狂怒', 'ゴーティス・フューリー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只鱼族怪兽和对方场上1只怪兽为对象才能发动。那2只怪兽直到下次的自己准备阶段除外。 ②：除外状态的卡存在，自己场上有鱼族怪兽特殊召唤的场合，把魔法与陷阱区域（表侧表示）·墓地的这张卡除外才能发动。自己场上的全部鱼族怪兽的攻击力直到回合结束时上升除外状态的卡数量×100。'),
(72309040, 'Ghoti of the Deep Beyond', '至深游魊', '最果てのゴーティス', 'Synchro Monster', 'Fish', 'WATER', 10, -1, NULL, '鱼族调整1只以上＋调整以外的怪兽1只以上 ①：这张卡的原本攻击力变成除外状态的怪兽数量×500。 ②：对方回合，这张卡同调召唤的场合才能发动。场上的卡全部除外。 ③：这张卡从怪兽区域除外的下个回合的准备阶段才能发动。除外状态的这张卡特殊召唤。'),
(95265975, 'Ghoul with an Appetite', '贪食的食尸鬼', '大食いグール', 'Normal Monster', 'Zombie', 'DARK', 4, 1600, 1200, '无论怎么吃也不会饱的怪兽。'),
(78266168, 'Giant Axe Mummy', '巨大木乃伊', 'ジャイアントマミー', 'Effect Monster', 'Zombie', 'EARTH', 5, 1700, 2000, '这张卡1个回合可以有1次变回里侧守备表示。里侧守备表示的这张卡受到攻击，攻击的怪兽的攻击力比这张卡的守备力低的场合，攻击的怪兽破坏。'),
(60619435, 'Giant Ballgame', '巨强投球', 'G・ボール・シュート', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡发动的回合的自己主要阶段才能发动。从自己墓地选1只6星以下的昆虫族怪兽特殊召唤。 ②：把手卡1只昆虫族怪兽给对方观看，以对方场上1只表侧表示怪兽和持有比给人观看的怪兽低的攻击力的自己场上1只昆虫族怪兽为对象才能发动。那2只怪兽的控制权交换。这个效果让自己得到控制权的怪兽变成昆虫族。'),
(58012707, 'Giant Ballpark', '巨强棒球场', 'G・ボールパーク', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：伤害计算时才能发动。那次战斗发生的双方的战斗伤害变成0，从自己卡组把1只4星以下的昆虫族怪兽送去墓地。这个效果让通常怪兽被送去墓地的场合，可以再从自己的手卡·卡组·墓地选那些同名怪兽任意数量特殊召唤。 ②：自己场上的怪兽被对方的效果送去墓地的场合才能发动。从自己墓地选1只昆虫族通常怪兽特殊召唤。'),
(38229962, 'Giant Beetrooper Invincible Atlas', '大骑甲虫 无敌阿特拉斯', '大騎甲虫インヴィンシブル・アトラス', 'Link Monster', 'Insect', 'EARTH', NULL, 3000, NULL, '昆虫族怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：连接召唤的这张卡在攻击力是3000以下的场合不会成为对方的效果的对象，不会被对方的效果破坏。 ②：只要这张卡在怪兽区域存在，自己不是昆虫族怪兽不能特殊召唤。 ③：可以把自己场上1只昆虫族怪兽解放，从以下效果选择1个发动。 ●从卡组把1只「骑甲虫」怪兽特殊召唤。 ●这张卡的攻击力直到回合结束时上升2000。'),
(41762634, 'Giant Flea', '吸血跳蚤', '吸血ノミ', 'Normal Monster', 'Insect', 'EARTH', 4, 1500, 1200, '攻击力高强的巨型吸血跳蚤，轻视它会非常危险。'),
(95178994, 'Giant Germ', '巨型病毒', 'ジャイアントウィルス', 'Effect Monster', 'Fiend', 'DARK', 2, 1000, 100, '①：这张卡被战斗破坏送去墓地的场合发动。给与对方500伤害。那之后，可以从卡组把「巨型病毒」任意数量攻击表示特殊召唤。'),
(58185394, 'Giant Kozaky', '巨大平庸鬼', 'G・コザッキー', 'Effect Monster', 'Fiend', 'DARK', 4, 2500, 2400, '场上没有「平庸鬼」表侧表示存在的场合，这张卡破坏。场上表侧表示存在的这张卡被破坏的场合，给与那个时候的控制者基本分为这张卡的原本攻击力数值的伤害。'),
(8170654, 'Giant Kra-Corn', '巨型章玉米', 'ジャイアント・タコーン', 'Effect Monster', 'Plant', 'EARTH', 8, 1000, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡守备表示特殊召唤，那只对方怪兽的攻击对象转移为这张卡进行伤害计算。 ②：以「巨型章玉米」以外的自己场上1只植物族怪兽为对象才能发动。那只怪兽和这张卡的攻击力变成那2只的原本攻击力合计数值。'),
(72299832, 'Giant Mech-Soldier', '机械巨兵', '機械の巨兵', 'Normal Monster', 'Machine', 'EARTH', 6, 1750, 1900, '巨斧的一击可以割开大地。'),
(16955631, 'Giant Mimighoul', '巨怪・迷拟宝箱鬼', 'ジャイアント・ミミグル', 'XYZ Monster', 'Rock', 'EARTH', 1, 1300, 2000, '1星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。从卡组把1张「迷拟宝箱鬼」卡加入手卡。 ②：只要对方场上有里侧表示怪兽存在，超量怪兽以外的自己的「迷拟宝箱鬼」怪兽可以直接攻击。 ③：把这张卡1个超量素材取除，以最多有对方场上的里侧表示怪兽数量的场上的表侧表示卡为对象才能发动。那些卡破坏，给与对方破坏数量×1000伤害。'),
(73698349, 'Giant Orc', '巨大兽人', 'ジャイアント・オーク', 'Effect Monster', 'Fiend', 'DARK', 4, 2200, NULL, '这张卡攻击的场合，战斗阶段结束时变成守备表示。直到下次的自己回合结束时这张卡的表示形式不能变更。'),
(92723496, 'Giant Pairfish', '龙宫的双使者', '竜宮のツガイ', 'Effect Monster', 'Wyrm', 'WATER', 6, 2000, 1200, '「龙宫的双使者」的效果1回合只能使用1次。 ①：把手卡1只怪兽丢弃才能发动。从卡组把1只4星以下的幻龙族怪兽特殊召唤。'),
(97017120, 'Giant Rat', '巨大老鼠', '巨大ネズミ', 'Effect Monster', 'Beast', 'EARTH', 4, 1400, 1450, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的地属性怪兽攻击表示特殊召唤。'),
(58831685, 'Giant Red Seasnake', '海鳞蛇', 'シーザリオン', 'Normal Monster', 'Aqua', 'WATER', 4, 1800, 800, '居住在海洋里的蛇型怪兽，它会去咬任何接近的物体。'),
(80280944, 'Giant Rex', '巨大恐龙', 'ジャイアント・レックス', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 2000, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡不能直接攻击。 ②：这张卡被除外的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡的攻击力上升除外的自己的恐龙族怪兽数量×200。'),
(41403766, 'Giant Scorpion of the Tundra', '冻土带的大蝎', 'ツンドラの大蠍', 'Normal Monster', 'Insect', 'EARTH', 3, 1100, 1000, '不是在沙漠而是分布在冰土带上的罕见的深蓝色的蝎子。'),
(57043117, 'Giant Soldier of Steel', '钢铁巨兵', '鋼鉄の巨兵', 'XYZ Monster', 'Rock', 'EARTH', 3, 1300, 2000, '岩石族3星怪兽×2 只要这张卡在场上表侧表示存在，这张卡不受这张卡以外的怪兽的效果影响。1回合1次，把这张卡1个超量素材取除才能发动。这张卡的守备力直到结束阶段时上升1000，这个回合，对方的卡的效果发生的对自己的效果伤害变成0。这个效果在对方回合也能发动。'),
(13039848, 'Giant Soldier of Stone', '岩石巨兵', '岩石の巨兵', 'Normal Monster', 'Rock', 'EARTH', 3, 1300, 2000, '岩石的巨人兵，巨腕的攻击能震动大地。'),
(43986064, 'Giant Starfall', '巨星坠', '巨星墜とし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '不能对应这张卡的发动让不持有等级的怪兽的效果发动。 ①：以不持有等级的场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽直到回合结束时攻击力变成0，不能把效果发动，不会被战斗破坏。这个回合，那只表侧表示怪兽的战斗发生的对双方的战斗伤害变成一半。'),
(80723580, 'Giant Trap Hole', '大落穴', '大落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '同时有2只以上的怪兽特殊召唤成功时才能发动。场上存在的怪兽全部破坏。'),
(42703248, 'Giant Trunade', '飓风', 'ハリケーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上的魔法·陷阱卡全部回到持有者手卡。'),
(96981563, 'Giant Turtle Who Feeds on Flames', '食火的大龟', '炎を食らう大亀', 'Normal Monster', 'Aqua', 'WATER', 5, 1400, 1800, '以深红甲壳为特征的乌龟。据说曾吞下了火焰。'),
(39526584, 'Gift Card', '礼品卡', 'ギフトカード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回复3000基本分。'),
(82257940, 'Gift Exchange', '礼物交换', 'プレゼント交換', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方玩家各自从自己卡组选1张卡里侧表示除外。这个回合的结束阶段，双方各自把作为对方的玩家除外的那张卡加入自己手卡。'),
(93912846, 'Gift Fiend Token', '复活礼物', 'リバイバル・ギフト', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(98792570, 'Gift of the Martyr', '继承之力', '受け継がれる力', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只怪兽送去墓地。选择自己场上1只怪兽。选择的那只怪兽的攻击力，在发动回合的结束阶段前上升送去墓地的那张卡的攻击力的数值。'),
(98299011, 'Gift of The Mystical Elf', '圣精灵的祝福', 'ホーリー・エルフの祝福', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己回复场上的怪兽数量×300基本分。'),
(43793530, 'Giga Gagagigo', '吉咖・咖咖吉哥', 'ギガ・ガガギゴ', 'Normal Monster', 'Reptile', 'WATER', 5, 2450, 1500, '为了对抗强大的邪恶，各种肉体改造的结果得到了惊人的力量，但作为其代价丧失了正义之心。'),
(8471389, 'Giga-Tech Wolf', '高科技狼', 'ギガテック・ウルフ', 'Normal Monster', 'Machine', 'FIRE', 4, 1200, 1400, '全身由钢铁制成的狼，用锋利的牙齿撕咬敌人。'),
(47606319, 'Gigantes', '癸干忒斯', 'ギガンテス', 'Effect Monster', 'Rock', 'EARTH', 4, 1900, 1300, '这张卡不能通常召唤。从自己墓地把1只地属性怪兽除外的场合可以特殊召唤。 ①：这张卡被战斗破坏送去墓地的场合发动。场上的魔法·陷阱卡全部破坏。'),
(11132674, 'Gigantic "Champion" Sargas', '超巨霸“冠军”飒嘉斯', 'ギガンティック“チャンピオン”サルガス', 'XYZ Monster', 'Machine', 'FIRE', 8, 2800, 1500, '8星怪兽×2只以上 「巨大喷流“冠军”尾宿五」1回合1次也能在自己场上的「护宝炮妖」超量怪兽上面重叠来超量召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡持有超量素材的场合才能发动。从卡组把1张「护宝炮妖」卡或者「兽带斗神」卡加入手卡。 ②：场上的超量素材被取除的场合，以场上1张卡为对象才能发动。那张卡破坏或回到手卡。'),
(82116191, 'Gigantic Cephalotus', '巨大土瓶草', 'ギガント・セファロタス', 'Effect Monster', 'Plant', 'EARTH', 4, 1850, 700, '只要这张卡在场上表侧表示存在，每次场上存在的植物族怪兽被送去墓地，这张卡的攻击力上升200。'),
(54498517, 'Gigantic Spright', '超巨霸・电光闪灵', 'ギガンティック・スプライト', 'XYZ Monster', 'Thunder', 'DARK', 2, 1600, 1600, '2星怪兽×2 这张卡超量召唤的场合，可以让自己场上的连接2怪兽作为2星怪兽来成为素材。这个卡名的②的效果1回合只能使用1次。 ①：有融合·同调·超量·连接怪兽的其中任意种在作为超量素材中的这张卡的原本攻击力变成2倍。 ②：自己主要阶段才能发动。自己场上1个超量素材取除，从卡组把1只2星怪兽特殊召唤。这个效果的发动后，直到回合结束时双方不是2星·2阶·连接2的怪兽不能特殊召唤。'),
(34047456, 'Gigantic Thundercross', '超巨霸・雷霆交叉击', 'ギガンティック・サンダークロス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己和对方的除外状态的卡数量差的数量的双方的场上·墓地的怪兽为对象才能发动。那些怪兽除外。那之后，对方可以从自身卡组把1只怪兽特殊召唤。'),
(63422098, 'Giganticastle', '鬼岩城', '鬼岩城', 'Synchro Monster', 'Rock', 'EARTH', 9, 2900, 2800, '调整＋调整以外的怪兽1只以上 这张卡的攻击力·守备力上升作为这张卡的同调素材的调整以外的怪兽数量×200的数值。'),
(33621868, 'Giganto', '铁球巨人', 'ギガント', 'Normal Monster', 'Machine', 'DARK', 5, 1700, 1800, '振舞着带刺的铁球进行攻击。'),
(53257892, 'Gigaplant', '巨型植物', 'ギガプラント', 'Gemini Monster', 'Plant', 'EARTH', 6, 2400, 1200, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●1回合1次，自己主要阶段才能发动。从自己的手卡·墓地选1只昆虫族或者植物族的怪兽特殊召唤。'),
(58330108, 'Gigarays Gandora the Dragon of Destruction', '破坏龙 钢多拉－烈光闪', '破壊竜ガンドラ－ギガ・レイズ', 'Effect Monster', 'Dragon', 'DARK', 8, NULL, NULL, '这张卡不能通常召唤。把这张卡以外的自己的手卡·场上2只怪兽送去墓地的场合可以特殊召唤。 ①：这张卡的攻击力上升除外中的卡数量×300。 ②：1回合1次，把基本分支付一半才能发动。自己墓地的「甘多拉」怪兽种类对应的以下适用。 ●1种类：这张卡以外的场上的卡全部破坏。 ●2种类：这张卡以外的场上的卡全部除外。 ●3种类以上：这张卡以外的双方的场上·墓地的卡全部除外。'),
(79080761, 'Gigastone Omega', '巨石终极龙', 'ギガストーン・オメガ', 'Effect Monster', 'Rock', 'EARTH', 5, 1000, 2300, '这张卡不能通常召唤。把自己墓地存在的2只地属性怪兽从游戏中除外的场合可以特殊召唤。自己场上表侧表示存在的这张卡被卡的效果送去墓地时，对方场上存在的魔法·陷阱卡全部破坏。'),
(17241941, 'Gigathunder Giclops', '大雷陀螺仪独眼巨人', 'ダイカミナリ・ジャイクロプス', 'Pendulum Tuner Effect Monster', 'Thunder', 'WIND', 4, 1400, 1700, '从额外卡组特殊召唤的这张卡被同调召唤使用的场合除外。这个卡名的②③的怪兽效果1回合各能使用1次。 ①：这张卡召唤成功的场合才能发动。这张卡的表示形式变更。 ②：这张卡的表示形式变更的场合，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡破坏。 ③：这张卡在灵摆区域被破坏的场合才能发动。选自己的灵摆区域1张卡回到持有者手卡。'),
(53776525, 'Gigobyte', '吉哥百特', 'ギゴバイト', 'Normal Monster', 'Reptile', 'WATER', 1, 350, 300, '现在虽然还拥有温和的心，但却背负着被邪恶之心侵蚀的命运。'),
(38445524, 'Gil Garth', '屠杀巨灵', 'ギル・ガース', 'Normal Monster', 'Fiend', 'DARK', 4, 1800, 1200, '身穿钢铁铠甲的杀戮机器。使用巨刀攻击。'),
(45894482, 'Gilasaurus', '俊足之基拉龙', '俊足のギラザウルス', 'Effect Monster', 'Dinosaur', 'EARTH', 3, 1400, 400, '①：这张卡可以从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤成功的场合发动。对方可以选自身墓地1只怪兽特殊召唤。'),
(69933858, 'Gilford the Legend', '传说的战士 吉尔福德', 'ギルフォード・ザ・レジェンド', 'Effect Monster', 'Warrior', 'EARTH', 8, 2600, 2000, '这张卡不能特殊召唤。这张卡召唤成功时，可以把自己墓地存在的装备卡尽可能装备到自己场上的战士族怪兽上。'),
(36354007, 'Gilford the Lightning', '闪电之战士 吉尔福德', 'ギルフォード・ザ・ライトニング', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 1400, '这张卡也能把3只怪兽解放作召唤。 ①：把3只怪兽解放对这张卡的上级召唤成功的场合发动。对方场上的怪兽全部破坏。'),
(76436988, 'Gillagillancer', '闪闪枪兵', 'ギラギランサー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2200, 800, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。只要这张卡在场上表侧表示存在，自己在每次结束阶段受到500分伤害。');